package com.travelbird.ai.service;
import static org.mockito.Mockito.*;import com.travelbird.ai.dto.request.AiRecommendationRequest;import com.travelbird.global.error.*;import com.travelbird.user.service.ActiveUserGuard;import org.junit.jupiter.api.Test;
class ActiveAiRecommendationServiceTest{@Test void inactiveUserCannotQueueOrPoll(){var users=mock(ActiveUserGuard.class);var delegate=mock(AiRecommendationService.class);doThrow(new BusinessException(ErrorCode.USER_NOT_ACTIVE)).when(users).requireActiveUserForUpdate(3L);doThrow(new BusinessException(ErrorCode.USER_NOT_ACTIVE)).when(users).requireActiveUser(3L);var service=new ActiveAiRecommendationService(users,delegate);org.assertj.core.api.Assertions.assertThatThrownBy(()->service.request(3L,mock(AiRecommendationRequest.class))).isInstanceOf(BusinessException.class);org.assertj.core.api.Assertions.assertThatThrownBy(()->service.status(3L,7L)).isInstanceOf(BusinessException.class);verifyNoInteractions(delegate);}}
